

UPDATE public.schacht SET geom = ST_Transform(ST_SetSRID(geom, 4326), 2056);
UPDATE public.trasse SET geom = ST_Transform(ST_SetSRID(geom, 4326), 2056);


SELECT setval(pg_get_serial_sequence('public.schacht', 'id'), (SELECT MAX(id) FROM public.schacht));
SELECT setval(pg_get_serial_sequence('public.trasse', 'id'), (SELECT MAX(id) FROM public.trasse));
